<?php
namespace App\Livewire\Investor\Support;
use App\Models\SupportTicket;use App\Services\SupportTicketService;use Illuminate\Validation\Rule;use Livewire\Attributes\Layout;use Livewire\Component;use Livewire\WithPagination;
#[Layout('layouts.investor')] class Index extends Component{use WithPagination;public bool $showCreate=false;public string $category='general',$subject='',$message='',$priority='normal';public function create(SupportTicketService $service):void{$data=$this->validate(['category'=>['required',Rule::in(SupportTicket::CATEGORIES)],'subject'=>['required','string','max:255'],'message'=>['required','string','max:5000'],'priority'=>['required',Rule::in(SupportTicket::INVESTOR_PRIORITIES)]]);$ticket=$service->create(auth()->user()->investor,auth()->user(),$data['category'],$data['subject'],$data['message'],$data['priority']);$this->reset(['showCreate','subject','message']);session()->flash('success','Обращение создано.');$this->redirectRoute('investor.support.show',$ticket,navigate:true);}public function render(){return view('livewire.investor.support.index',['tickets'=>SupportTicket::where('investor_id',auth()->user()->investor->id)->latest('last_message_at')->paginate(15)])->title('Поддержка — CEO Money');}}
